WITH exploded AS (SELECT id, service, log_ts, level, k, value FROM app_logs LATERAL VIEW EXPLODE(context) t AS k, value) SELECT id, k, ROW_NUMBER() OVER w_grp AS row_seq, ROW_NUMBER() OVER w_hist AS event_seq, LAST_VALUE(k, TRUE) OVER (PARTITION BY level ORDER BY log_ts, id, k ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_k, ROW_NUMBER() OVER w_running AS event_seq_2, ROW_NUMBER() OVER w_running AS seq_no FROM exploded WHERE level = 'INFO' WINDOW w_grp AS (ORDER BY log_ts DESC, id, k), w_hist AS (PARTITION BY service ORDER BY log_ts DESC, id, k), w_running AS (PARTITION BY service ORDER BY log_ts, id, k)
